-- ============================================================================
-- DOKKAI N3 · 42 hari (dibuat oleh /opt/data/scripts/gen-dokkai.py)
--
-- Tiap hari: 5 kalimat memakai kata hari itu + 4 soal BAHASA JEPANG.
-- Teks punya 2 versi: kanji (teks_jp) & kana penuh (teks_furi) → furigana
-- dipasang otomatis oleh aset/furigana.js.
--
-- Aman dijalankan berulang (on conflict update).
-- ============================================================================

create table if not exists public.dokkai (
  id        bigserial primary key,
  level     text not null default 'n3',
  hari_ke   int  not null,
  tema      text,
  judul_jp  text not null,
  judul_id  text,
  teks_jp   text not null,
  teks_furi text,
  teks_id   text,
  soal      jsonb not null default '[]'::jsonb,
  created_at timestamptz not null default now(),
  unique (level, hari_ke)
);

alter table public.dokkai enable row level security;

drop policy if exists "baca dokkai" on public.dokkai;
create policy "baca dokkai" on public.dokkai for select to authenticated using (true);

drop policy if exists "admin tulis dokkai" on public.dokkai;
create policy "admin tulis dokkai" on public.dokkai for all to authenticated
  using (public.apakah_admin()) with check (public.apakah_admin());

